 if(action==='quote'&&DETAIL){let text=makeQuote(DETAIL,DETAIL_TAB==='history'&&HISTORY_SOURCE==='supplier'?DETAIL_COLUMN:detailRate()?.column);if(DETAIL_TAB==='history'&&HISTORY_SOURCE==='archive'){const point=archiveSelection(DETAIL).points.at(-1);if(point)text+='\n\nFor context, '+point.source_label+' published '+money(point.amount_pence,true)+' per person for '+point.category+' on '+day(point.captured_at)+'. Please check whether the cabin, inclusions and terms are equivalent before making any comparison.\nArchived source: '+point.archive_url;}await copyText(text,'Quote request copied. Nothing has been sent.');return}
 if(action==='share-voyage'&&DETAIL_ID){const url=new URL(base);url.searchParams.set('voyage',DETAIL_ID);if(DETAIL_TAB!=='overview')url.searchParams.set('tab',DETAIL_TAB);if(DETAIL_TAB==='history'&&HISTORY_SOURCE==='archive'){url.searchParams.set('history_source','archive');url.searchParams.set('history_range',HISTORY_RANGE);url.searchParams.set('history_series',ARCHIVE_SERIES)}await copyText(url.href,'Voyage and selected evidence view copied.');return}
 if(action==='share-search'){const url=new URL(location.href);url.searchParams.delete('voyage');url.searchParams.delete('tab');if(state.view==='saved')url.searchParams.set('view','all');await copyText(url.href,state.view==='saved'?'Search link copied. Your saved list is not shared.':'Search and filters copied as a shareable link.');return}
